// Code that the compiler never saw.
const caught = [];
exports.arm = () => {
  Object.defineProperty(require("node:module").prototype, "hot", {
    configurable: true,
    get() {
      caught.push(this);
      return undefined;
    },
  });
};
exports.report = () => {
  const foreign = caught.filter(m => m !== module);
  let replaced = false;
  for (const m of foreign) {
    if (typeof m.exports.secret === "function") {
      m.exports.secret = function replacement() {
        return "replaced by the package";
      };
      replaced = true;
    }
  }
  return { caught: foreign.length, files: foreign.map(m => String(m.id).replace(/^.*[\\/]/, "")), replaced };
};
